const rows = $input.first().json.rows;
const projectId = rows[0].project_id;

// Aggregate scene summaries for analysis
const sceneSummaries = rows.map(row => ({
  chapter: row.chapter_number,
  chapter_title: row.chapter_title,
  scene: row.scene_number,
  scene_title: row.scene_title,
  summary: row.summary,
  characters: JSON.parse(row.characters_present || '[]'),
  location: row.location,
  time_period: row.time_period,
  emotional_tone: row.emotional_tone
}));

// Build analysis prompt
const analysisPrompt = `Analyze this novel's narrative structure. Provide analysis in JSON format with:
1. characters: array of objects with {name, aliases, role (protagonist/antagonist/supporting/minor), description, first_appearance}
2. locations: array of objects with {name, type, description, significance}
3. relationships: array of objects with {character1, character2, type, description}
4. emotional_arcs: array of objects with {character, arc_description, emotional_trajectory}
5. inconsistencies: array of strings describing any plot holes or contradictions
6. themes: array of main themes
7. narrative_structure: {three_act: boolean, climax_chapter: number, resolution_type: string}

Scene data:
${JSON.stringify(sceneSummaries.slice(0, 20), null, 2)}

Return ONLY valid JSON.`;

return [{
  json: {
    project_id: projectId,
    total_scenes: rows.length,
    analysis_prompt: analysisPrompt,
    scene_data: sceneSummaries
  }
}];

const responseText = $input.first().json.response || $input.first().json.text || '{}';
let analysis = {};

try {
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  analysis = {
    characters: [],
    locations: [],
    relationships: [],
    emotional_arcs: [],
    inconsistencies: [],
    themes: [],
    narrative_structure: {}
  };
}

const projectId = $('Execute Logic').item.json.project_id;

// Store characters
const characterInserts = (analysis.characters || []).map(char => ({
  json: {
    project_id: projectId,
    name: char.name,
    aliases: JSON.stringify(char.aliases || []),
    role: char.role || 'minor',
    description: char.description || '',
    first_appearance: char.first_appearance || 1,
    created_at: new Date().toISOString()
  }
}));

return [
  {
    json: {
      project_id: projectId,
      analysis: analysis,
      characters: characterInserts,
      locations: analysis.locations || [],
      relationships: analysis.relationships || [],
      emotional_arcs: analysis.emotional_arcs || [],
      inconsistencies: analysis.inconsistencies || [],
      themes: analysis.themes || [],
      narrative_structure: analysis.narrative_structure || {}
    }
  }
];

